#include <bits/stdc++.h>
using namespace std;

class DSU {
    vector<int> par, size;
public:
    explicit DSU(int cnt) : par(cnt + 1), size(cnt + 1, 1) {
        iota(par.begin(), par.end(), 0);
    }
    int find(int vertex) {
        while (par[vertex] != vertex) {
            par[vertex] = par[par[vertex]];
            vertex = par[vertex];
        }
        return vertex;
    }
    bool unite(int first, int second) {
        first = find(first);
        second = find(second);
        if (first == second) {
            return false;
        }
        if (size[first] < size[second]) {
            swap(first, second);
        }
        par[second] = first;
        size[first] += size[second];
        return true;
    }
    int get_size(int vertex) {
        return size[find(vertex)];
    }
};

struct Edge {
    int first, second;
    long long cost;
};

optional<long long> mst(int n, vector<Edge> edges) {
    sort(edges.begin(), edges.end(), [](const Edge& l, const Edge& r) {
        return l.cost < r.cost;
    });
    DSU sets(n);
    int chosen = 0;
    long long total = 0;
    for (const Edge& edge : edges) {
        if (sets.unite(edge.first, edge.second)) {
            total += edge.cost;
            ++chosen;
        }
    }

    if (chosen != n - 1) {
        return nullopt;
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<Edge> edges(m);
    for (Edge& edge : edges) {
        cin >> edge.first >> edge.second >> edge.cost;
    }
    auto answer = mst(n, edges);
    if (answer.has_value()) {
        cout << *answer << '\n';
    } else {
        cout << "IMPOSSIBLE\n";
    }
}

